package com.example.shortener.feature.user.controller;
import com.example.shortener.common.exception.BusinessException; import com.example.shortener.feature.user.dto.RegisterForm; import com.example.shortener.feature.user.service.UserService; import jakarta.validation.Valid; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.validation.BindingResult; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.support.RedirectAttributes;
@Controller public class AuthController { private final UserService service; public AuthController(UserService s){service=s;} @GetMapping("/login") public String login(){return "auth/login";} @GetMapping("/register") public String register(Model m){if(!m.containsAttribute("form"))m.addAttribute("form",new RegisterForm());return "auth/register";} @PostMapping("/register") public String register(@Valid @ModelAttribute("form")RegisterForm f,BindingResult b,RedirectAttributes r){if(b.hasErrors())return "auth/register";try{service.register(f);r.addFlashAttribute("success","Registered! Please log in.");return "redirect:/login";}catch(BusinessException e){b.reject("form",e.getMessage());return "auth/register";}}}
